public Long saveVideo(ProductVideoSaveDTO saveDTO, String userName) {
    validateUseRange(saveDTO.getUseRange());
    validateExternalCompliance(saveDTO);
    if (StringUtils.isBlank(saveDTO.getJfrogPath()) || StringUtils.isBlank(saveDTO.getFileName())) {
        log.error("save product video failed, jfrogPath or fileName is blank. identification: {}",
                saveDTO.getIdentification());
        throw ErrorCode.PARAMS_ERROR.throwException("视频文件路径和文件名不能为空");
    }

    DocumentInfoEntity entity = new DocumentInfoEntity();
    fillEntityFromDTO(entity, saveDTO);
    // 视频行约定：c_type='productDocuments'、c_file_form='video'、c_version=''、c_status='1'、
    // c_store_type='jfrog'、c_upload_status='1'（视频无文本不扫敏感词）
    entity.setType(TYPE_PRODUCT_DOCUMENTS);
    entity.setFileForm(FILE_FORM_VIDEO);
    entity.setVersion(StringUtils.EMPTY);
    entity.setStatus(STATUS_VALID);
    entity.setStoreType(STORE_TYPE_JFROG);
    entity.setDocumentSource(DOCUMENT_SOURCE_UPLOAD);
    entity.setUploadStatus(UPLOAD_STATUS_PASSED);
    entity.setUploader(userName);
    // 状态机：新增默认下架；转码 processing；审核态按开放范围
    entity.setShelfStatus(SHELF_STATUS_OFF);
    entity.setProcessState(PROCESS_STATE_PROCESSING);
    entity.setAuditState(USE_RANGE_EXTERNAL.equals(saveDTO.getUseRange()) ? AUDIT_STATE_WAIT : AUDIT_STATE_NONE);
    entity.setSortValue(saveDTO.getSortValue() == null ? DEFAULT_SORT_VALUE : saveDTO.getSortValue());
    entity.setCreateTime(new Date());
    entity.setUpdateTime(new Date());
    entity.setUploadTime(new Date());
    documentInfoDao.save(entity);

    saveRelList(entity.getId(), saveDTO);
    sendTranscodeTask(entity);
    log.info("save product video success. id: {}, identification: {}, name: {}",
            entity.getId(), saveDTO.getIdentification(), saveDTO.getName());
    return entity.getId();
}

/**
 * 发送转码任务到 multimediaTaskAddQueue
 * <p>HLS 转码必发；用户未传封面时加发截帧封面任务。
 *
 * @param entity 视频记录实体（需已生成id）
 */
private void sendTranscodeTask(DocumentInfoEntity entity) {
    List<MdMultimediaTaskAddDTO> taskList = new ArrayList<>(2);
    String taskBusinessId = String.valueOf(entity.getId());
    String taskInfo = org.springframework.util.Base64Utils
            .encodeToString(entity.getJfrogPath().getBytes());

    MdMultimediaTaskAddDTO hlsTask = new MdMultimediaTaskAddDTO();
    hlsTask.setTaskBusinessType(MultimediaTaskBusinessTypeEnum.PRODUCT_VIDEO.toString());
    hlsTask.setTaskBusinessId(taskBusinessId);
    hlsTask.setTaskType(MultimediaTaskTypeEnum.FORMAT_CONVERT_MP4_TO_HLS.toString());
    hlsTask.setTaskInfo(taskInfo);
    taskList.add(hlsTask);

    if (StringUtils.isBlank(entity.getCoverUrl())) {
        MdMultimediaTaskAddDTO coverTask = new MdMultimediaTaskAddDTO();
        coverTask.setTaskBusinessType(MultimediaTaskBusinessTypeEnum.PRODUCT_VIDEO.toString());
        coverTask.setTaskBusinessId(taskBusinessId);
        coverTask.setTaskType(MultimediaTaskTypeEnum.SCREEN_SHOTS_COVER.toString());
        coverTask.setTaskInfo(taskInfo);
        taskList.add(coverTask);
    }
    producerService.send(MULTIMEDIA_TASK_ADD_QUEUE, JSON.toJSONString(taskList));
    log.info("send multimedia transcode task. id: {}, taskCount: {}", entity.getId(), taskList.size());
}

/**
 * 实体转列表行 DTO
 *
 * @param entity              视频记录实体
 * @param modelRelMap         型号关联分组（按视频记录id）
 * @param versionRelMap       版本关联分组（按视频记录id）
 * @param typeNameMap         资料类型显示名映射
 * @param ownerDisplayNameMap 负责人显示名映射
 * @return 列表行 DTO
 */
private ProductVideoPageItemDTO transToPageItemDTO(DocumentInfoEntity entity,
                                                   Map<Long, List<DocumentVideoModelRelEntity>> modelRelMap,
                                                   Map<Long, List<DocumentVideoVersionRelEntity>> versionRelMap,
                                                   Map<String, String> typeNameMap,
                                                   Map<String, String> ownerDisplayNameMap) {
    ProductVideoPageItemDTO itemDTO = new ProductVideoPageItemDTO();
    itemDTO.setId(entity.getId());
    itemDTO.setName(entity.getDocumentName());
    itemDTO.setDocumentType(entity.getDocumentType());
    itemDTO.setDocumentTypeName(typeNameMap.getOrDefault(entity.getDocumentType(), entity.getDocumentType()));
    List<DocumentVideoModelRelEntity> modelRelList =
            modelRelMap.getOrDefault(entity.getId(), Collections.emptyList());
    itemDTO.setModelList(modelRelList.stream().map(rel -> {
        ProductVideoPageItemDTO.ModelItem modelItem = new ProductVideoPageItemDTO.ModelItem();
        modelItem.setModelId(rel.getrModelShipId());
        modelItem.setShipModelName(rel.getShipModelName());
        modelItem.setMaterialCode(rel.getMaterialCode());
        return modelItem;
    }).collect(Collectors.toList()));
    itemDTO.setVersionList(versionRelMap.getOrDefault(entity.getId(), Collections.emptyList())
            .stream().map(DocumentVideoVersionRelEntity::getVersion).collect(Collectors.toList()));
    itemDTO.setUseRange(entity.getUseRange());
    itemDTO.setOwner(entity.getOwner());
    itemDTO.setOwnerDisplayName(ownerDisplayNameMap.get(entity.getOwner()));
    itemDTO.setShelfStatus(entity.getShelfStatus());
    itemDTO.setProcessState(entity.getProcessState());
    itemDTO.setSortValue(entity.getSortValue());
    itemDTO.setCoverUrl(entity.getCoverUrl());
    itemDTO.setDuration(entity.getDuration());
    itemDTO.setCreateTime(entity.getCreateTime() != null
            ? DateUtil.dateToStr(entity.getCreateTime(), "yyyy-MM-dd HH:mm:ss") : null);
    return itemDTO;
}
